/**
 * Brands a value from outside the API, like a URL segment, as `API.ProductId`. A value from a response is branded already.
 *
 * @example
 * const id = toProductId('1');
 */
export const toProductId = (value: string): API.ProductId => value as API.ProductId;

/**
 * Brands a value from outside the API, like a URL segment, as `API.ArticleId`. A value from a response is branded already.
 *
 * @example
 * const id = toArticleId('1');
 */
export const toArticleId = (value: string): API.ArticleId => value as API.ArticleId;

/**
 * Brands a value from outside the API, like a URL segment, as `API.EmployeeId`. A value from a response is branded already.
 *
 * @example
 * const id = toEmployeeId('1');
 */
export const toEmployeeId = (value: string): API.EmployeeId => value as API.EmployeeId;

/**
 * Whether a `400` body is the validation error kizuna sends, rather than a `400` the route declares itself.
 *
 * @example
 * if (result.status === 400 && isValidationError(result.body)) {
 *     console.log(result.body.errors);
 * }
 */
export const isValidationError = (body: unknown): body is API.ValidationError =>
    typeof body === 'object' && body !== null && 'errors' in body && Array.isArray(body.errors);

/**
 * A client for this API. Pass the base URL and anything else the runtime takes.
 */
export const createClient = (config: ClientConfig): Client => buildClient(routes, config) as unknown as Client;

/**
 * What the client knows about one response: nothing for a body it reads as
 * JSON, how to read one that is not, the media type for one that streams.
 */
export type GeneratedResponse =
    | Record<string, never>
    | {
          read: 'bytes' | 'text';
      }
    | {
          stream: true;
          contentType: string;
      };

/**
 * One route in the table: how to reach it, and how to read each status it
 * answers with.
 */
export interface GeneratedRoute {
    method: string;
    path: string;
    contentType?: string;
    responses: Record<number, GeneratedResponse>;
}

/**
 * The route table, nested the way the client is.
 */
export interface GeneratedRoutes {
    [key: string]: GeneratedRoutes | GeneratedRoute;
}

/**
 * The request onRequest receives before it is sent. A header set on headers
 * is sent with it.
 */
export interface OutgoingRequest {
    url: string;
    method: string;
    headers: Headers;
    route: GeneratedRoute;
}

/**
 * Where the client sends its requests, and what it adds to each one.
 */
export interface ClientConfig {
    baseUrl: string;
    baseHeaders?: Record<string, string>;
    credentials?: RequestInit['credentials'];
    fetch?: typeof fetch;
    onRequest?: (request: OutgoingRequest) => void | Promise<void>;
    retry?: RetryOptions;
    reconnect?: ReconnectOptions;
}

/**
 * Retries a GET, HEAD, OPTIONS, PUT or DELETE that failed on the network or
 * was answered 429 or 503, waiting what Retry-After asks or backing off.
 */
export interface RetryOptions {
    /**
     * Attempts in all, the first included.
     */
    maximumAttempts?: number;
    /**
     * Milliseconds the first backoff waits at most.
     */
    initialDelay?: number;
    /**
     * Milliseconds any wait may take.
     */
    maximumDelay?: number;
}

/**
 * Reconnects an event stream on a GET, HEAD, OPTIONS, PUT or DELETE when its
 * connection drops, sending the id of the last event as Last-Event-ID.
 */
export interface ReconnectOptions {
    /**
     * Reconnections in a row before the stream fails. An event received resets the count.
     */
    maximumAttempts?: number;
    /**
     * Milliseconds to wait before reconnecting, until the server sends a retry field.
     */
    reconnectionTime?: number;
    /**
     * Milliseconds the wait may grow to after reconnections in a row that fail.
     */
    maximumDelay?: number;
}

/**
 * One method on the client. Its '~route' names the method it sends and
 * whether its response streams, so a wrapper like @kizunajs/tanstack-query
 * reads both off the client.
 */
export type ClientMethod<Method extends string, Streams extends boolean, Args, Result> = ({} extends Args
    ? (args?: Args) => Promise<Result>
    : (args: Args) => Promise<Result>) & {
    readonly '~route': GeneratedRoute & {
        readonly method: Method;
        readonly streams: Streams;
    };
};

interface CallArgs {
    params?: Record<string, unknown>;
    query?: Record<string, unknown>;
    body?: unknown;
    headers?: Record<string, string | undefined>;
    fetchOptions?: RequestInit;
}

/**
 * Dates go on the wire as ISO 8601, everything else as String gives it.
 */
const serializeValue = (value: unknown): string => (value instanceof Date ? value.toISOString() : String(value));

const buildPath = (path: string, params: Record<string, unknown> = {}): string =>
    path.replace(/:([A-Za-z_][A-Za-z0-9_]*)/g, (_, name: string) => {
        const value = params[name];
        if (value === undefined) throw new Error('Missing path parameter: ' + name);
        return encodeURIComponent(serializeValue(value));
    });

/**
 * An array repeats its key, and an undefined or null field is left out.
 */
const buildSearchParams = (fields: Record<string, unknown>): URLSearchParams => {
    const params = new URLSearchParams();
    for (const [key, value] of Object.entries(fields)) {
        if (value === undefined || value === null) continue;
        for (const item of Array.isArray(value) ? value : [value]) params.append(key, serializeValue(item));
    }
    return params;
};

const buildFormData = (fields: Record<string, unknown>): FormData => {
    const formData = new FormData();
    for (const [key, value] of Object.entries(fields)) {
        for (const item of Array.isArray(value) ? value : [value]) {
            if (item instanceof Blob) formData.append(key, item);
            else if (item !== undefined && item !== null) formData.append(key, typeof item === 'string' ? item : JSON.stringify(item));
        }
    }
    return formData;
};

/**
 * A multipart body leaves Content-Type to fetch, which adds the boundary.
 */
const encodeBody = (route: GeneratedRoute, body: unknown, headers: Headers): NonNullable<RequestInit['body']> => {
    switch (route.contentType) {
        case 'multipart/form-data':
            return body instanceof FormData ? body : buildFormData(body as Record<string, unknown>);
        case 'application/x-www-form-urlencoded':
            if (!headers.has('Content-Type')) headers.set('Content-Type', 'application/x-www-form-urlencoded');
            return buildSearchParams(body as Record<string, unknown>);
        default:
            if (!headers.has('Content-Type')) headers.set('Content-Type', 'application/json');
            return JSON.stringify(body);
    }
};

const parseJson = (text: string): unknown => {
    try {
        return JSON.parse(text) as unknown;
    } catch {
        return text;
    }
};

interface ServerSentEvent {
    event?: string;
    data: unknown;
    id?: string;
    retry?: number;
}

/**
 * A lone carriage return at the end may be half of CRLF, so it waits for more
 * unless the stream is over.
 */
const findLineEnd = (buffer: string, final: boolean): { index: number; length: number } | undefined => {
    for (let index = 0; index < buffer.length; index += 1) {
        const character = buffer[index];
        if (character === '\n') return { index, length: 1 };
        if (character === '\r') {
            if (index + 1 < buffer.length) return { index, length: buffer[index + 1] === '\n' ? 2 : 1 };
            if (final) return { index, length: 1 };
            return undefined;
        }
    }
    return undefined;
};

/**
 * Reads text/event-stream as the WHATWG HTML specification parses it.
 */
interface EventStreamState {
    lastEventId: string;
    reconnectionTime: number;
}

async function* readEvents(
    body: ReadableStream<Uint8Array>,
    state: EventStreamState = {
        lastEventId: '',
        reconnectionTime: 3000,
    }
): AsyncGenerator<ServerSentEvent> {
    const reader = body.getReader();
    const decoder = new TextDecoder();
    let buffer = '';
    let first = true;
    let dataLines: string[] = [];
    let eventType = '';
    let lastEventId = state.lastEventId;
    let retry: number | undefined;

    const dispatch = (): ServerSentEvent | undefined => {
        state.lastEventId = lastEventId;
        if (dataLines.length === 0) {
            eventType = '';
            return undefined;
        }
        const message: ServerSentEvent = {
            data: parseJson(dataLines.join('\n')),
        };
        if (eventType !== '') message.event = eventType;
        if (lastEventId !== '') message.id = lastEventId;
        if (retry !== undefined) message.retry = retry;
        dataLines = [];
        eventType = '';
        retry = undefined;
        return message;
    };

    const processLine = (line: string): ServerSentEvent | undefined => {
        if (line === '') return dispatch();
        if (line.startsWith(':')) return undefined;
        const separator = line.indexOf(':');
        const field = separator === -1 ? line : line.slice(0, separator);
        let value = separator === -1 ? '' : line.slice(separator + 1);
        if (value.startsWith(' ')) value = value.slice(1);
        switch (field) {
            case 'event':
                eventType = value;
                break;
            case 'data':
                dataLines.push(value);
                break;
            case 'id':
                if (!value.includes('\0')) lastEventId = value;
                break;
            case 'retry':
                if (/^\d+$/.test(value)) {
                    retry = Number(value);
                    state.reconnectionTime = Math.min(retry, 3_600_000);
                }
                break;
        }
        return undefined;
    };

    try {
        for (;;) {
            const { done, value } = await reader.read();
            let chunk = done ? decoder.decode() : decoder.decode(value, { stream: true });
            if (first && chunk.length > 0) {
                if (chunk.charCodeAt(0) === 0xfeff) chunk = chunk.slice(1);
                first = false;
            }
            buffer += chunk;
            for (;;) {
                const lineEnd = findLineEnd(buffer, done);
                if (lineEnd === undefined) break;
                const line = buffer.slice(0, lineEnd.index);
                buffer = buffer.slice(lineEnd.index + lineEnd.length);
                const message = processLine(line);
                if (message !== undefined) yield message;
            }
            if (done) return;
        }
    } finally {
        void reader.cancel().catch(() => undefined);
    }
}

async function* reconnectingEvents(
    first: Response,
    reopen: (lastEventId: string) => Promise<Response>,
    options: ReconnectOptions,
    signal: AbortSignal | null | undefined
): AsyncGenerator<ServerSentEvent> {
    const maximumAttempts = options.maximumAttempts ?? 5;
    const maximumDelay = options.maximumDelay ?? 30_000;
    const state: EventStreamState = {
        lastEventId: '',
        reconnectionTime: options.reconnectionTime ?? 3000,
    };
    let response: Response | undefined = first;
    let attempts = 0;
    let failure: unknown;
    for (;;) {
        if (response?.body) {
            try {
                for await (const message of readEvents(response.body, state)) {
                    attempts = 0;
                    failure = undefined;
                    yield message;
                }
            } catch (error) {
                failure = error;
            }
        }
        if (signal?.aborted) throw signal.reason;
        if (attempts >= maximumAttempts) {
            if (failure !== undefined) throw failure;
            return;
        }
        attempts += 1;
        const ceiling = Math.min(maximumDelay, state.reconnectionTime * 2 ** (attempts - 1));
        await wait(state.reconnectionTime + Math.random() * Math.max(0, ceiling - state.reconnectionTime), signal);
        try {
            response = await reopen(state.lastEventId);
        } catch (error) {
            if (signal?.aborted) throw error;
            failure = error;
            response = undefined;
            continue;
        }
        if (response.status === 204) return;
        const contentType = response.headers.get('content-type') ?? '';
        if (response.status !== first.status || !contentType.toLowerCase().startsWith('text/event-stream')) {
            throw new Error('Reconnecting to the event stream failed with status ' + response.status);
        }
    }
}

async function* readText(body: ReadableStream<Uint8Array>): AsyncGenerator<string> {
    const reader = body.getReader();
    const decoder = new TextDecoder();
    try {
        for (;;) {
            const { done, value } = await reader.read();
            if (done) {
                const tail = decoder.decode();
                if (tail.length > 0) yield tail;
                return;
            }
            const text = decoder.decode(value, { stream: true });
            if (text.length > 0) yield text;
        }
    } finally {
        void reader.cancel().catch(() => undefined);
    }
}

async function* readBytes(body: ReadableStream<Uint8Array>): AsyncGenerator<Uint8Array> {
    const reader = body.getReader();
    try {
        for (;;) {
            const { done, value } = await reader.read();
            if (done) return;
            yield value;
        }
    } finally {
        void reader.cancel().catch(() => undefined);
    }
}

const readStream = (body: ReadableStream<Uint8Array>, contentType: string): AsyncIterable<unknown> => {
    const essence = (contentType.split(';')[0] ?? '').trim().toLowerCase();
    if (essence === 'text/event-stream') return readEvents(body);
    if (essence.startsWith('text/')) return readText(body);
    return readBytes(body);
};

const IDEMPOTENT_METHODS = new Set(['GET', 'HEAD', 'OPTIONS', 'PUT', 'DELETE']);

const RETRY_STATUSES = new Set([429, 503]);

const retryAfter = (header: string | null): number | undefined => {
    if (header === null) return undefined;
    if (/^\d+$/.test(header.trim())) return Number(header.trim()) * 1000;
    const date = Date.parse(header);
    return Number.isNaN(date) ? undefined : Math.max(0, date - Date.now());
};

const wait = (milliseconds: number, signal: AbortSignal | null | undefined): Promise<void> =>
    new Promise((resolve, reject) => {
        if (signal?.aborted) {
            reject(signal.reason);
            return;
        }
        const onAbort = () => {
            clearTimeout(timer);
            reject(signal?.reason);
        };
        const timer = setTimeout(() => {
            signal?.removeEventListener('abort', onAbort);
            resolve();
        }, milliseconds);
        signal?.addEventListener('abort', onAbort, {
            once: true,
        });
    });

const send = async (url: string, init: RequestInit, route: GeneratedRoute, config: ClientConfig): Promise<Response> => {
    const fetcher = config.fetch ?? fetch;
    const retry = config.retry;
    if (retry === undefined || !IDEMPOTENT_METHODS.has(route.method)) return fetcher(url, init);
    const maximumAttempts = retry.maximumAttempts ?? 3;
    const initialDelay = retry.initialDelay ?? 500;
    const maximumDelay = retry.maximumDelay ?? 30_000;
    for (let attempt = 1; ; attempt += 1) {
        const backoff = Math.random() * Math.min(maximumDelay, initialDelay * 2 ** (attempt - 1));
        let response: Response;
        try {
            response = await fetcher(url, init);
        } catch (error) {
            if (attempt >= maximumAttempts || init.signal?.aborted || !(error instanceof TypeError)) throw error;
            await wait(backoff, init.signal);
            continue;
        }
        if (attempt >= maximumAttempts || !RETRY_STATUSES.has(response.status)) return response;
        const asked = retryAfter(response.headers.get('retry-after'));
        if (asked !== undefined && asked > maximumDelay) return response;
        await response.body?.cancel();
        await wait(asked ?? backoff, init.signal);
    }
};

const buildMethod = (route: GeneratedRoute, config: ClientConfig) => {
    const call = async (args: CallArgs = {}) => {
        const query = args.query === undefined ? '' : buildSearchParams(args.query).toString();
        const url = config.baseUrl + buildPath(route.path, args.params) + (query.length > 0 ? '?' + query : '');
        const prepare = async (lastEventId = ''): Promise<RequestInit> => {
            const headers = new Headers(config.baseHeaders);
            for (const [name, value] of Object.entries(args.headers ?? {})) {
                if (value !== undefined) headers.set(name, value);
            }
            if (lastEventId !== '') headers.set('Last-Event-ID', lastEventId);
            const init: RequestInit = {
                method: route.method,
                headers,
            };
            if (args.body !== undefined) init.body = encodeBody(route, args.body, headers);
            if (config.credentials !== undefined) init.credentials = config.credentials;
            await config.onRequest?.({
                url,
                method: route.method,
                headers,
                route,
            });
            return {
                ...init,
                ...args.fetchOptions,
            };
        };

        const response = await send(url, await prepare(), route, config);
        const responseHeaders: Record<string, string> = {};
        response.headers.forEach((value, name) => {
            responseHeaders[name] = value;
        });
        const declared = route.responses[response.status];
        if (declared !== undefined && 'stream' in declared && response.body !== null) {
            const essence = (declared.contentType.split(';')[0] ?? '').trim().toLowerCase();
            const reconnect = essence === 'text/event-stream' && IDEMPOTENT_METHODS.has(route.method) ? config.reconnect : undefined;
            const reopen = async (lastEventId: string) => send(url, await prepare(lastEventId), route, config);
            return {
                status: response.status,
                body: reconnect
                    ? reconnectingEvents(response, reopen, reconnect, args.fetchOptions?.signal)
                    : readStream(response.body, declared.contentType),
                headers: responseHeaders,
            };
        }
        if (declared !== undefined && 'read' in declared) {
            return {
                status: response.status,
                body: declared.read === 'bytes' ? new Uint8Array(await response.arrayBuffer()) : await response.text(),
                headers: responseHeaders,
            };
        }
        const text = await response.text();
        return {
            status: response.status,
            body: text.length > 0 ? parseJson(text) : undefined,
            headers: responseHeaders,
        };
    };
    const streams = Object.values(route.responses).some((response) => 'stream' in response);
    return Object.defineProperty(call, '~route', {
        value: {
            ...route,
            streams,
        },
    });
};

const isRoute = (node: GeneratedRoutes | GeneratedRoute): node is GeneratedRoute => typeof node['method'] === 'string';

const buildTree = (routes: GeneratedRoutes, config: ClientConfig): Record<string, unknown> => {
    const tree: Record<string, unknown> = {};
    for (const [key, node] of Object.entries(routes)) {
        tree[key] = isRoute(node) ? buildMethod(node, config) : buildTree(node, config);
    }
    return tree;
};

/**
 * Sends the request context headers with every request. An explicit
 * baseHeaders entry wins.
 */
const buildClient = (routes: GeneratedRoutes, config: ClientConfig & { requestContext?: object }): Record<string, unknown> => {
    const contextHeaders: Record<string, string> = {};
    for (const [name, value] of Object.entries(config.requestContext ?? {})) {
        if (value !== undefined) contextHeaders[name] = String(value);
    }
    return buildTree(routes, {
        ...config,
        baseHeaders: {
            ...contextHeaders,
            ...config.baseHeaders,
        },
    });
};
